"use client";

import * as React from "react";
import { Reveal } from "../componentes/Reveal";

export type ProcessStep = {
  numero: string;
  title: string;
  description: string;
  duracao?: string;
  commitLabel?: string;
  commitOutput?: string;
};

export type ProcessProps = {
  eyebrow: string;
  title: React.ReactNode;
  description: React.ReactNode;
  steps: ProcessStep[];
};

function PipelineCard({ step, index }: { step: ProcessStep; index: number }) {
  return (
    <Reveal
      as="article"
      margin="-60px"
      delayMs={index * 60}
      className="group relative flex h-full flex-col overflow-hidden rounded border border-line bg-surface p-5 transition-colors hover:border-cyan/60 lg:p-6"
    >
      <div
        className="pointer-events-none absolute inset-0 opacity-0 transition-opacity duration-300 group-hover:opacity-100"
        style={{
          background:
            "radial-gradient(circle at 0% 0%, color-mix(in srgb, var(--cyan) 7%, transparent), transparent 52%)",
        }}
        aria-hidden="true"
      />

      <div className="relative flex h-full flex-col">
        <div className="flex items-start justify-between gap-3">
          <p className="font-mono text-xs uppercase tracking-[0.28em] text-cyan">{step.numero}</p>
          {step.duracao && (
            <span className="shrink-0 rounded border border-line px-2 py-0.5 font-mono text-[10px] text-gray-text">
              {step.duracao}
            </span>
          )}
        </div>

        <h3 className="mt-3 text-[clamp(1.25rem,2.2vw,1.75rem)] font-black leading-[1.05] tracking-tight text-foreground">
          {step.title}
        </h3>

        <p className="mt-3 flex-1 text-sm leading-relaxed text-gray-text">{step.description}</p>

        {(step.commitLabel || step.commitOutput) && (
          <div className="mt-4 border-t border-line pt-3 font-mono">
            {step.commitLabel && (
              <p className="truncate text-xs text-foreground">
                <span className="text-cyan">$</span> {step.commitLabel}
              </p>
            )}
            {step.commitOutput && (
              <p className="mt-1 truncate text-[11px] text-gray-text">
                <span className="text-cyan/60">&gt;</span> {step.commitOutput}
              </p>
            )}
          </div>
        )}
      </div>
    </Reveal>
  );
}

export function Process({ eyebrow, title, description, steps }: ProcessProps) {
  return (
    <section
      id="processo"
      aria-label="Processo de trabalho"
      className="relative overflow-hidden border-t border-line py-16 lg:py-24"
    >
      <div className="w-full px-5 sm:px-8 lg:px-10 2xl:px-14">
        <Reveal margin="-80px" className="mb-8 lg:mb-10">
          <p className="mb-4 font-mono text-xs uppercase tracking-[0.34em] text-cyan">{eyebrow}</p>
          <h2 className="text-[length:var(--text-h2)] font-black leading-[0.96] tracking-tight text-foreground">
            {title}
          </h2>
          <p className="mt-4 max-w-3xl text-base leading-relaxed text-gray-text">{description}</p>
        </Reveal>

        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-[repeat(auto-fit,minmax(14rem,1fr))]">
          {steps.map((step, index) => (
            <PipelineCard key={step.numero} step={step} index={index} />
          ))}
        </div>
      </div>
    </section>
  );
}
